const r=[{role:"chat",label:"聊天回复",description:"负责普通 QQ 对话的主要回复生成；它就是故障转移链的第一个模型。",restartHint:"改顺序即时生效（路由器按当前顺序挑选）。"},{role:"vision",label:"图片理解",description:"看图时使用：识别图片内容、决定表情与回复。",restartHint:"媒体组件在启动时读取该绑定，修改后需要重启。"},{role:"decision",label:"决策",description:"生活沙盒在需要判断“做什么”时的裁决模型。",restartHint:"沙盒运行期读取配置，改后即时生效。"},{role:"conversation",label:"会话判断",description:"对话运行期生成“这一轮怎么回”，受回复长度上限约束。",restartHint:"对话组件运行期读取，改后即时生效。"},{role:"extraction",label:"记忆抽取",description:"从高价值互动里提炼可长期保存的事实。",restartHint:"提取器运行期读取，改后即时生效。"},{role:"social",label:"社交判断",description:"群聊里判断“该不该说话、说什么更合适”。",restartHint:"社交观察者运行期读取，改后即时生效。"},{role:"planner",label:"任务规划（Planner）",description:"Agent 把一句话拆成可执行步骤时使用。",restartHint:"Agent 组件在启动时读取该绑定，修改后需要重启。"},{role:"evaluator",label:"任务评估（Evaluator）",description:"Agent 判断任务是否完成、要不要重规划。",restartHint:"Agent 组件在启动时读取该绑定，修改后需要重启。"},{role:"embedding",label:"向量检索（Embedding）",description:"把记忆转成向量以支持语义检索；需与向量模型匹配。",restartHint:"向量服务在启动时建立，修改后需要重启。"}];function i(e){return r.find(t=>t.role===e)}export{i as r};
